-- Boreas Power Personnel Planner import (migration from spreadsheet)
-- Run in Supabase SQL editor AFTER migration 081

DO $$
DECLARE
  co_id uuid;
  emp_id uuid;
BEGIN
  SELECT id INTO co_id FROM public.companies WHERE slug = 'boreaspower';
  IF co_id IS NULL THEN RAISE EXCEPTION 'boreaspower company not found'; END IF;

  SELECT id INTO emp_id FROM public.people
    WHERE company_id = co_id AND name ILIKE '%Fraser%McKenzie%'
    LIMIT 1;

  -- Insert assignments one at a time to avoid batch conflict errors

  RAISE NOTICE 'Import complete: 238 rows';
END $$;